-- ════════════════════════════════════════════════════════════════════════════════════
-- Nightly run: raw member → trigger → care-plan need → action → worklist
-- Run every night after 03_load.sql (and after POST /campaigns refreshes campaign_member).
-- Each statement is safe to re-run on the same day (G9: done/declined needs are never reopened early).
-- Generated by tools/gen_sql.py: the trigger and alert conditions come from rules/rule_condition.csv.
-- ════════════════════════════════════════════════════════════════════════════════════
USE ccl;

-- ── Step 1 · Who is in which campaign (owner = the highest-priority live campaign, G3) ──
-- campaign_member itself is refreshed by the API for each Live campaign:
--   DELETE FROM campaign_member WHERE campaign_id = ?;
--   INSERT INTO campaign_member (member_id, campaign_id, holdout, added_on)
--   SELECT m.member_id, ?, CASE WHEN CRC32(CONCAT(?, ':', m.member_id)) % 100 < ? THEN 1 ELSE 0 END, rc.run_date
--   FROM member m JOIN run_config rc WHERE <campaign.where_sql>;
TRUNCATE TABLE work_member;
INSERT INTO work_member (member_id, owner_campaign, owner_priority, trigger_mode, trigger_list)
SELECT member_id, campaign_id, priority, trigger_mode, trigger_list
FROM (
  SELECT cm.member_id, c.campaign_id, c.priority, c.trigger_mode, c.trigger_list,
         ROW_NUMBER() OVER (PARTITION BY cm.member_id ORDER BY c.priority, c.campaign_id) AS rn
  FROM campaign_member cm
  JOIN campaign c ON c.campaign_id = cm.campaign_id AND c.status = 'Live'
  JOIN member m ON m.member_id = cm.member_id
  WHERE cm.holdout = 0                       -- the 10% control group gets nothing
    AND m.consent <> 'declined'              -- G2: declined consent = no further contact
    AND COALESCE(m.excluded, 0) = 0          -- G1c: extract exclusions (cancer, palliative, dialysis …)
) x
WHERE rn = 1;

-- ── Step 2 · Raw member → trigger (rule_condition; rule_trigger.use_variant picks extract flag or rulebook thresholds) ──
DELETE FROM member_signal WHERE run_date = (SELECT run_date FROM run_config WHERE id = 1);
-- @@SIGNALS@@

-- ── Step 3 · Score: R = C + M + K + U + A, tier, alert colour, contact priority (rulebook §2, §4) ──
UPDATE member m JOIN run_config rc
SET m.r_total = COALESCE(m.clinical_score, 0) + COALESCE(m.comorbid_complication_score, 0) + COALESCE(m.kidney_score, 0)
              + COALESCE(m.utilization_score, 0) + COALESCE(m.age_sex_score, 0),
    m.scored_on = rc.run_date;
UPDATE member m JOIN rule_tier t ON m.r_total BETWEEN t.r_min AND t.r_max SET m.tier = t.tier;

INSERT INTO work_member (member_id, n_fired, has_trig4)
SELECT s.member_id, SUM(s.state = 'fired'), MAX(s.trigger_code = 'Trig4' AND s.state = 'fired')
FROM member_signal s JOIN run_config rc ON s.run_date = rc.run_date
GROUP BY s.member_id
ON DUPLICATE KEY UPDATE n_fired = VALUES(n_fired), has_trig4 = VALUES(has_trig4);

UPDATE member m JOIN run_config rc LEFT JOIN work_member w ON w.member_id = m.member_id
SET m.alert = CASE
    WHEN @@RED@@ THEN 'RED'
    WHEN @@AMBER@@ THEN 'AMBER'
    WHEN COALESCE(w.n_fired, 0) > 0 THEN 'YELLOW'     -- off target or an overdue test
    ELSE 'GREEN' END;

-- contact priority: first matching row of rule_priority (e.g. AMBER + post-discharge = P1)
INSERT INTO work_member (member_id, match_order)
SELECT m.member_id, MIN(p.match_order)
FROM member m
JOIN rule_priority p ON p.alert = m.alert
LEFT JOIN work_member w ON w.member_id = m.member_id
WHERE p.needs_trigger = '' OR (p.needs_trigger = 'Trig4' AND COALESCE(w.has_trig4, 0) = 1)
GROUP BY m.member_id
ON DUPLICATE KEY UPDATE match_order = VALUES(match_order);
UPDATE member m JOIN work_member w ON w.member_id = m.member_id JOIN rule_priority p ON p.match_order = w.match_order
SET m.contact_priority = p.priority;

-- ── Step 4 · Trigger → care-plan need (only campaign members; business-mode campaigns keep only their listed triggers) ──
-- 4a. a declined need comes back only after its 90-day hold (G4)
UPDATE care_plan_need n
JOIN run_config rc
JOIN member_signal s ON s.member_id = n.member_id AND s.trigger_code = n.trigger_code AND s.run_date = rc.run_date AND s.state = 'fired'
JOIN rule_trigger t ON t.trigger_code = n.trigger_code
SET n.status = 'open', n.gap_state = 'Potential', n.hold_until = NULL, n.closed_on = NULL,
    n.due_date = DATE_ADD(rc.run_date, INTERVAL t.due_days DAY)
WHERE n.status = 'declined' AND n.hold_until <= rc.run_date;

-- 4b. new needs (existing ones keep their status: G9)
INSERT INTO care_plan_need (member_id, trigger_code, dm_module, class, class_order, trigger_order, slot, status, gap_state, due_date, evidence, opened_on)
SELECT s.member_id, s.trigger_code, t.dm_module, t.class, t.class_order, t.trigger_order, 'FUTURE', 'open', 'Potential',
       DATE_ADD(rc.run_date, INTERVAL t.due_days DAY), s.evidence, rc.run_date
FROM member_signal s
JOIN run_config rc ON s.run_date = rc.run_date
JOIN rule_trigger t ON t.trigger_code = s.trigger_code
JOIN work_member w ON w.member_id = s.member_id AND w.owner_campaign IS NOT NULL
WHERE s.state = 'fired'
  AND (w.trigger_mode = 'all' OR CONCAT(',', w.trigger_list, ',') LIKE CONCAT('%,', s.trigger_code, ',%'))
ON DUPLICATE KEY UPDATE evidence = VALUES(evidence);

-- 4c. a need whose trigger stopped firing was met in claims → Closed (the only way a gap closes)
UPDATE care_plan_need n
JOIN run_config rc
JOIN work_member w ON w.member_id = n.member_id AND w.owner_campaign IS NOT NULL
LEFT JOIN member_signal s ON s.member_id = n.member_id AND s.trigger_code = n.trigger_code AND s.run_date = rc.run_date AND s.state = 'fired'
SET n.status = 'done', n.slot = 'CLOSED', n.gap_state = 'Closed', n.closed_on = COALESCE(n.closed_on, rc.run_date)
WHERE s.member_id IS NULL AND (n.status = 'open' OR n.gap_state = 'Reported');
UPDATE action a JOIN care_plan_need n ON n.member_id = a.member_id AND n.trigger_code = a.trigger_code
SET a.status = 'done', a.closed_at = NOW()
WHERE a.kind IN ('care_plan', 'follow_up') AND a.status = 'open' AND n.gap_state = 'Closed';   -- the claim did the verifying

-- ── Step 5 · Slots: CURRENT = top 3 by class order (safety → acute → uncontrolled → barrier → gap → goal), NEXT = 4–6 ──
TRUNCATE TABLE work_rank;
INSERT INTO work_rank (member_id, trigger_code, rn)
SELECT member_id, trigger_code, ROW_NUMBER() OVER (PARTITION BY member_id ORDER BY class_order, trigger_order)
FROM care_plan_need WHERE status = 'open';
UPDATE care_plan_need n JOIN work_rank r ON r.member_id = n.member_id AND r.trigger_code = n.trigger_code
SET n.slot = CASE WHEN r.rn <= 3 THEN 'CURRENT' WHEN r.rn <= 6 THEN 'NEXT' ELSE 'FUTURE' END;
UPDATE care_plan_need SET slot = 'CLOSED' WHERE status <> 'open';

-- ── Step 6 · Need → action: exactly one open care-plan action per CURRENT need (G7) ──
INSERT INTO action (member_id, trigger_code, kind, title, channel, owner_role, due_date, status, created_by, created_at)
SELECT n.member_id, n.trigger_code, 'care_plan', t.action_title, t.channel, t.owner_role, n.due_date, 'open', 'nightly', NOW()
FROM care_plan_need n
JOIN rule_trigger t ON t.trigger_code = n.trigger_code
LEFT JOIN action a ON a.member_id = n.member_id AND a.trigger_code = n.trigger_code AND a.kind IN ('care_plan', 'follow_up') AND a.status = 'open'
WHERE n.slot = 'CURRENT' AND n.status = 'open' AND a.action_id IS NULL;   -- an open follow-up on the need counts as its action

-- ── Step 7 · The nudge: one contact per member — a call by SLA (P1 today, P2 next day, P3 in 3 days) or a digital nudge (P4) ──
INSERT INTO work_member (member_id, has_open_contact)
SELECT member_id, 1 FROM action
WHERE status = 'open' AND kind IN ('nudge', 'call', 'follow_up', 'retry', 'escalation')
GROUP BY member_id
ON DUPLICATE KEY UPDATE has_open_contact = 1;
INSERT INTO work_member (member_id, reached_14d)       -- G3: no new outreach within 14 days of a reached call
SELECT o.member_id, 1 FROM outcome o JOIN run_config rc
WHERE o.reached = 1 AND o.recorded_at >= DATE_SUB(rc.run_date, INTERVAL 14 DAY)
GROUP BY o.member_id
ON DUPLICATE KEY UPDATE reached_14d = 1;
INSERT INTO work_member (member_id, top_need)
SELECT n.member_id, t.name
FROM care_plan_need n JOIN work_rank r ON r.member_id = n.member_id AND r.trigger_code = n.trigger_code AND r.rn = 1
JOIN rule_trigger t ON t.trigger_code = n.trigger_code
ON DUPLICATE KEY UPDATE top_need = VALUES(top_need);

INSERT INTO action (member_id, kind, title, channel, owner_role, due_date, status, created_by, created_at)
SELECT m.member_id,
       CASE WHEN p.sla_days IS NULL THEN 'nudge' ELSE 'call' END,
       CASE WHEN p.sla_days IS NULL THEN CONCAT('Digital nudge: ', w.top_need) ELSE CONCAT(m.contact_priority, ' call: ', w.top_need) END,
       p.channel, 'Nurse',
       DATE_ADD(rc.run_date, INTERVAL COALESCE(p.sla_days, 2) DAY), 'open', 'nightly', NOW()
FROM member m
JOIN run_config rc
JOIN work_member w ON w.member_id = m.member_id AND w.owner_campaign IS NOT NULL AND w.top_need IS NOT NULL
JOIN rule_priority p ON p.priority = m.contact_priority AND p.alert = m.alert
WHERE COALESCE(w.has_open_contact, 0) = 0 AND COALESCE(w.reached_14d, 0) = 0;

-- ── Step 8 · Worklist orchestration (rulebook §4) ──
-- Order: safety or RED first → tier 4…1 → campaign priority → most overdue. One row per member, led by
-- their most urgent open nurse action. Nurses are matched by language, round-robin, within daily capacity;
-- anything over capacity is 'queued' and rolls to the next day.
TRUNCATE TABLE worklist;
INSERT INTO worklist (work_date, member_id, nurse_id, rank_no, nurse_rank, action_id, priority, alert, tier, reason, due_by, status)
SELECT z.run_date, z.member_id, z.nurse_id, z.rank_no, z.nurse_rank, z.action_id, z.contact_priority, z.alert, z.tier, z.title, z.due_date,
       CASE WHEN z.nurse_rank <= z.daily_capacity THEN 'today' ELSE 'queued' END
FROM (
  SELECT rc.run_date, q.*, nl.nurse_id, nu.daily_capacity,
         ROW_NUMBER() OVER (PARTITION BY nl.nurse_id ORDER BY q.rank_no) AS nurse_rank      -- capacity counts across all of a nurse's languages
  FROM (
    SELECT l.*,
           ROW_NUMBER() OVER (ORDER BY l.urgent DESC, l.tier DESC, l.owner_priority, l.due_date, l.r_total DESC, l.member_id) AS rank_no,
           ROW_NUMBER() OVER (PARTITION BY l.lang ORDER BY l.urgent DESC, l.tier DESC, l.owner_priority, l.due_date, l.r_total DESC, l.member_id) AS lang_rn
    FROM (
      SELECT a.member_id, a.action_id, a.title, a.due_date, m.contact_priority, m.alert, m.tier, m.r_total, w.owner_priority,
             CASE WHEN m.alert = 'RED' OR m.priority_clinical_review = 1 THEN 1 ELSE 0 END AS urgent,
             CASE WHEN m.language IN (SELECT language FROM nurse_language) THEN m.language ELSE 'English' END AS lang,
             ROW_NUMBER() OVER (PARTITION BY a.member_id
                                ORDER BY CASE a.kind WHEN 'call' THEN 1 WHEN 'retry' THEN 2 ELSE 3 END, a.due_date) AS lead_rn
      FROM action a
      JOIN member m ON m.member_id = a.member_id
      JOIN work_member w ON w.member_id = a.member_id
      WHERE a.status = 'open' AND a.kind IN ('call', 'follow_up', 'retry')   -- escalations go to the clinical lead, not the nurse list
    ) l
    WHERE l.lead_rn = 1
  ) q
  JOIN run_config rc
  JOIN (SELECT language, COUNT(*) AS n_nurses FROM nurse_language GROUP BY language) lc ON lc.language = q.lang
  JOIN nurse_language nl ON nl.language = q.lang AND nl.lang_idx = MOD(q.lang_rn - 1, lc.n_nurses) + 1   -- language first, then round-robin
  JOIN nurse nu ON nu.nurse_id = nl.nurse_id
) z;

-- the member's open actions go to the nurse who has them on the list
UPDATE action a JOIN worklist w ON w.member_id = a.member_id
SET a.assignee = w.nurse_id
WHERE a.status = 'open' AND a.assignee IS NULL;
